/// <summary>
/// MPJ_24248 Pricing Data Extract DCP 28/07/2022
/// </summary>
class METPriceDataFeedTaskService extends SysOperationServiceBase
{
    Batch           batchTask;
    Batch           batchTaskCurrent;
    BatchHeader     batchHeader;
    RefRecId        batchJobId;
    RefRecId        headerTaskId;
    boolean         isExecutingInBatch, isMainBatchTask;
    METTaskGuid     taskGuid;
    UserConnection  secondConnection;
    Name            attributeName, attributeTypeName;
    TransDate       todayDate;

    METPriceDataFeedContract    dataContract;
    
}

Method.Source:
    /// <summary>
    /// processing logic
    /// </summary>
    /// <param name = "_dataContract">The data contract</param>
    public void process(METPriceDataFeedContract _dataContract)
    {
        #OCCRetryCount

        try
        {
            this.initialise(_dataContract);

            if(!this.validate())
            {
                error("@MET:PriceDataFeedBatchTaskFailed");
                
                if(isExecutingInBatch)
                {
                    //ensure batch status is "Error"
                    throw Exception::Error;
                }
                else
                {
                    //dont throw error when run from GUI
                    return;
                }
            }

            this.cleanup();
            this.processTask(true);

            if(isMainBatchTask)
            {
                //last run of main task thread to make sure all customers have been processed
                this.processTask(false);
            }
        }
        catch (Exception::UpdateConflict)
        {
            if (appl.ttsLevel() == 0)
            {
                if (xSession::currentRetryCount() >= #RetryNum)
                {
                    error("@MET:PriceDataFeedBatchTaskFailed");
                    throw Exception::UpdateConflictNotRecovered;
                }
                else
                {
                    retry;
                }
            }
            else
            {
                error("@MET:PriceDataFeedBatchTaskFailed");
                throw Exception::UpdateConflict;
            }
        }
        catch (Exception::Deadlock)
        {
            if (appl.ttsLevel() == 0)
            {
                if (xSession::currentRetryCount() >= #RetryNum)
                {
                    error("@MET:PriceDataFeedBatchTaskFailed");
                    throw Exception::UpdateConflictNotRecovered;
                }
                else
                {
                    retry;
                }
            }
            else
            {
                error("@MET:PriceDataFeedBatchTaskFailed");
                throw Exception::Deadlock;
            }
        }
        catch
        {
            error("@MET:PriceDataFeedBatchTaskFailed");
            throw Exception::Error;
            
        }
    }

    /// <summary>Initialise global variables</summary>
    /// <param name = "_dataContract">The data contract</param>
    public void initialise(METPriceDataFeedContract _dataContract)
    {
        dataContract        = _dataContract;
        
        isMainBatchTask     = dataContract.parmIsMainBatchTask();
        batchTaskCurrent    = this.getCurrentBatchTask();
        batchJobId          = batchTaskCurrent.BatchJobId;
        headerTaskId        = batchTaskCurrent.RecId;
        batchHeader         = BatchHeader::construct(batchJobId);
        isExecutingInBatch  = batchTaskCurrent ? true : false;
        taskGuid            = str2Guid(dataContract.parmTaskGuidStr());
        secondConnection    = new UserConnection();
        [attributeName, attributeTypeName] = this.getSalesOrderAttribute();
        todayDate           = DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone());

    }

    /// <summary>Check that process should run</summary>
    /// <returns>The result of the validation</returns>
    public boolean validate()
    {
        boolean Ok = true;

        if(!taskGuid)
        {
            Ok = checkFailed("@MET:TaskGuidMissing");
        }

        return Ok;
    }

    /// <summary>Process the batch tasks</summary>
    /// <param name = "_readPast">Table read past setting</param>
    public void processTask(boolean _readPast)
    {
        METPriceDataFeed        priceDataFeed;	            //table used for top pick list
       
        priceDataFeed.setConnection(secondConnection);
        priceDataFeed.readPast(_readPast);              // skip or don't skip locked records

        do
        {
            secondConnection.ttsbegin();
                      
            select firstOnly pessimisticlock priceDataFeed;

            if(priceDataFeed)
            {
                this.processPriceDataFeed(priceDataFeed);

                priceDataFeed.delete();
            }

            secondConnection.ttscommit();
        }
        while(priceDataFeed);
    }

/// <summary>Constuct new object</summary>
/// <returns>New Service Object</returns>
public static METPriceDataFeedTaskService construct()
{
    return new METPriceDataFeedTaskService();
}

    /// <summary>
    /// Constuct and run a METPriceDataFeedTaskService. Used when process is run from GUI (not in Batch mode)
    /// </summary>
    /// <param name = "_serializedContractCon">Serialised data contract</param>
    public static void processAsync(container _serializedContractCon)	//must have Container as parameter
    {
        METPriceDataFeedTaskService     priceDataFeedTaskService;
        METPriceDataFeedContract        dataContract;
        Object  				        deserializedContract;
        str                             serializedContract;

        serializedContract      = conPeek(_serializedContractCon,1);
        deserializedContract    = FormJsonSerializer::deserializeObject(classIdGet(dataContract), serializedContract);
        dataContract            = deserializedContract as METPriceDataFeedContract;

        PriceDataFeedTaskService = METPriceDataFeedTaskService::construct();
        PriceDataFeedTaskService.process(dataContract);
    }

    /// <summary>Process the Price data feed records</summary>
    /// <param name = "_priceDataFeed">Price data feed record</param>
    public void processPriceDataFeed(METPriceDataFeed _priceDataFeed)
    {
        METPriceDataFeed    priceDataFeed = _priceDataFeed;

        GUPPricingAttributeHelper   pricingAttributeHelper = new GUPPricingAttributeHelper();
        GUPRetailPriceCheck         retailPriceCheck    = RetailPricingCalculatorCreator::getInstance().createPriceCheck();
        List                        priceDiscountLines  = new List(Types::Class);
        RetailPriceDiscountLine     priceDiscountLine   = new RetailPriceDiscountLine();

        retailPriceCheck.parmReportId(taskGuid);
        retailPriceCheck.parmCustAccount(priceDataFeed.CustAccount);
        retailPriceCheck.parmCustSiteId(priceDataFeed.InventSiteId);
        retailPriceCheck.parmPricingAttributeHelper(pricingAttributeHelper);

        priceDiscountLine.parmInventDimId(this.getInventDimId(priceDataFeed.InventSiteId));
        
        priceDiscountLine.parmCatalogRefRecId(0);
        priceDiscountLine.parmReferenceRecId(0);
        
        priceDiscountLine.parmItemId(priceDataFeed.ItemId);
        priceDiscountLine.parmQty(priceDataFeed.Quantity);
        priceDiscountLine.parmSalesUnit(priceDataFeed.UnitOfMeasure);
        
        priceDiscountLines.addEnd(priceDiscountLine);

        if(priceDataFeed.EventID)
        {
            if(attributeName && attributeTypeName)
            {
                retailPriceCheck.setSalesOrderAttributeByClassId(classNum(GUPPricingAttributeEcoResAttribute),              //class Id
                                                                    priceDataFeed.EventID,                                  // value of attribute
                                                                    classNum(GUPPricingAttributeProviderSalesTableAttribute), //attribute provider class Id
                                                                    attributeName,                                          // attribute name
                                                                    attributeTypeName);                                     //attribute type
            }
        }

        retailPriceCheck.calculatePriceDiscountsWithDateTime(priceDiscountLines, new System.DateTimeOffset(priceDataFeed.StartDate, System.TimeSpan::Zero));

        this.populatePriceDataExtract(priceDataFeed);

        this.cleanup();
    }

    /// <summary>
    /// Essentially a Copy of GUPPriceReportGenerateEngine.populatePriceReportResult().
    /// Populate Extract table instead of Report result table.
    /// </summary>
    /// <param name = "_priceDataFeed">Price data feed record</param>
    public void populatePriceDataExtract(METPriceDataFeed    _priceDataFeed)
    {
        GUPTmpPriceReportValues     tmpPriceReportValues;
        METPriceDataExtract         priceDataExtract;
        NumberSequenceReference     numberSequenceReference;
        NumberSeq                   numberSeq;
        METPriceDataFeed            priceDataFeed = _priceDataFeed;

        numberSequenceReference = GUPParameters::numRefMETPriceDataExtractId();
        
        if (numberSequenceReference)
        {
            numberSeq = NumberSeq::newGetNum(numberSequenceReference);
        }

        if(!numberSeq)
        {
            error("@MET:EntryNumberIdNumSeqFailed");
            throw Exception::Error;
        }

        Map metPriceListToBeKept = new Map(Types::Int64, Types::Container);

        while select minof(FromDate), maxof(ToDate), minof(RecId)
            from tmpPriceReportValues
            group by tmpPriceReportValues.AccountNum, tmpPriceReportValues.CurrencyCode, tmpPriceReportValues.ItemId, tmpPriceReportValues.VariantId,
                    tmpPriceReportValues.BasePrice, tmpPriceReportValues.TAJournalNum,
                    tmpPriceReportValues.MarginOffers, tmpPriceReportValues.MarginAmountList, tmpPriceReportValues.CalculatedMargin,
                    tmpPriceReportValues.DiscountOffers, tmpPriceReportValues.DiscountAmountList, tmpPriceReportValues.CalculatedDiscount,
                    tmpPriceReportValues.UnitPrice, tmpPriceReportValues.SalesPrice, tmpPriceReportValues.LineAmount
            where tmpPriceReportValues.ReportId == taskGuid
        {
            metPriceListToBeKept.add(tmpPriceReportValues.RecId, [tmpPriceReportValues.FromDate, tmpPriceReportValues.ToDate]);
        }

        RecordSortedList metListOfPriceDataExtract = new RecordSortedList(tableNum(METPriceDataExtract));
        metListOfPriceDataExtract.sortOrder(fieldNum(METPriceDataExtract, CustAccount),
                                    fieldNum(METPriceDataExtract, ItemId),
                                    fieldNum(METPriceDataExtract, InventSiteId),
                                    fieldNum(METPriceDataExtract, UnitOfMeasure),
                                    fieldNum(METPriceDataExtract, StartDate),
                                    fieldNum(METPriceDataExtract, Qty),
                                    fieldNum(METPriceDataExtract, EventId));


        ValidFromDate   metFromDate;
        ValidToDate     metToDate;
        RecId           metPriceValueRecId;
        GUPTmpPriceReportValues metTmpFinalPriceReportValues;

        MapEnumerator   metEnumerator = metPriceListToBeKept.getEnumerator();
        
        while (metEnumerator.moveNext())
        {
            metPriceValueRecId          = metEnumerator.currentKey();
            [metFromDate, metToDate]    = metEnumerator.currentValue();

            select firstonly metTmpFinalPriceReportValues
                where metTmpFinalPriceReportValues.RecId == metPriceValueRecId;
            
            if(metTmpFinalPriceReportValues)
            {
                priceDataExtract.clear();
                priceDataExtract.ExtractId       = str2Int(numberSeq.num());
                priceDataExtract.taskGuid        = taskGuid;

                priceDataExtract.initFromTmpPriceList(metTmpFinalPriceReportValues);
                priceDataExtract.enhanceFromPriceDataFeed(priceDataFeed);
                
                //Is the record going to be a duplicate?
                if(!METPriceDataExtract::existForCustItem(priceDataExtract.CustAccount,
                                                            priceDataExtract.ItemId,
                                                            priceDataExtract.InventSiteId,
                                                            priceDataExtract.UnitOfMeasure,
                                                            priceDataExtract.StartDate,
                                                            priceDataExtract.Qty,
                                                            priceDataExtract.EventId))
                {
                    this.updateChargeCodes(priceDataExtract, priceDataFeed);
                    priceDataExtract.reread();
                    priceDataExtract.updateTax();

                    metListOfPriceDataExtract.ins(priceDataExtract);
                }
            }
        }

        ttsbegin;
        metListOfPriceDataExtract.insertDatabase();
        ttscommit;
    }

    /// <summary>
    /// get the Sales Order attribute
    /// </summary>
    /// <returns>Container of names</returns>
    public container getSalesOrderAttribute()
    {
        GUPParameters                   gupParameters;
        EcoResAttribute                 attributes;
        EcoResAttributeType             attributeType;

        select firstonly Name from attributeType 
                
            join Name from attributes
                where   attributes.AttributeType == attributeType.RecId
            
            exists join gupParameters
                where gupParameters.METSalesEventAttribute  == attributes.RecId;

        return[attributes.Name, attributeType.Name];
    }

/// <summary>
/// In case this Task is being rerun by Batch framework due to a previous error. clean up intermediate tables.
/// </summary>
public void cleanUp()
{
    METPriceDataFeedHelper::cleanUp(taskGuid, secondConnection);
}

    /// <summary>
    /// Get an invent dim id
    /// </summary>
    /// <param name = "_inventSiteId">Invent site id</param>
    /// <returns>The invent dim id</returns>
    public InventDimId getInventDimId(InventSiteId _inventSiteId)
    {
        InventDim   inventDim;

        inventDim.clear();
        InventDim.InventSiteId  = _inventSiteId;

        return InventDim::findOrCreate(inventDim).inventDimId;
    }

/// <summary>
/// Calculate and populate the Charge codes
/// </summary>
/// <param name = "_priceDataExtract">Price data extract</param>
/// <param name = "_priceDataFeed">Price data feed</param>
public void updateChargeCodes(METPriceDataExtract _priceDataExtract, METPriceDataFeed _priceDataFeed)
{
    METSimulatedAutoCharges     simulatedAutoCharges;
    SalesTable                  salesTable;
    SalesLine                   salesLine;
    
    salesTable = this.BuildSalesTableTmp(_priceDataExtract);
    salesLine  = this.BuildSalesLineTmp(_priceDataExtract, salesTable);
        
    simulatedAutoCharges = METSimulatedAutoCharges::newFromSalesTmp(salesTable, salesLine);
    
    this.updateLineChargeCodes(simulatedAutoCharges, _priceDataExtract, salesTable, salesLine);
        
    //TODO: incomplete
    //this.updateHeaderChargeCodes(simulatedAutoCharges, _priceDataExtract, salesTable, salesLine);
    
}

    /// <summary>
    /// Calculate and populate the Charge codes
    /// </summary>
    /// <param name = "_simulatedAutoCharges">Simulated auto charge</param>
    /// <param name = "_priceDataExtract">Price data extract</param>
    /// <param name = "_salesTable">Sales table</param>
    /// <param name = "_salesLine">Sales line</param>
    public void updateHeaderChargeCodes(METSimulatedAutoCharges _simulatedAutoCharges,
                                        METPriceDataExtract _priceDataExtract,
                                        SalesTable _salesTable,
                                        SalesLine _salesLine)
    {
        METPriceDataExtract         priceDataExtract = _priceDataExtract;
        List                        matchedAutoChargeHeaderRecIdList;
        ListEnumerator              enumerator;
        MarkupAutoLine              markupAutoLine;
        MarkupAutoTable             markupAutoTable;
        MarkupTable                 markupTable;
        MarkupTrans                 markupTrans;

        matchedAutoChargeHeaderRecIdList = _simulatedAutoCharges.getMarkupAutoHeaders();

        enumerator = matchedAutoChargeHeaderRecIdList.getEnumerator();
        
        while (enumerator.moveNext())
        {
            markupAutoTable = MarkupAutoTable::metFindByRecId(str2int64(enumerator.current()));
            
            QueryRun qr = new QueryRun(this.buildMarkupAutoLineQuery(markupAutoTable, _simulatedAutoCharges.parameters));
        
            while (qr.next())
            {
                markupAutoLine = qr.get(tableNum(MarkupAutoLine));
                
                markupTrans = _simulatedAutoCharges.initializeMarkupTransFromParent(markupAutoLine);

                markupTable = MarkupTable::find(markupTrans.ModuleType, markupTrans.MarkupCode);

            }
        }
    }

    /// <summary>
    /// Calculate and populate the Charge codes
    /// </summary>
    /// <param name = "_simulatedAutoCharges">Simulated auto charge</param>
    /// <param name = "_priceDataExtract">Price data extract</param>
    /// <param name = "_salesTable">Sales table</param>
    /// <param name = "_salesLine">Sales line</param>
    public void updateLineChargeCodes(METSimulatedAutoCharges _simulatedAutoCharges, 
                                        METPriceDataExtract _priceDataExtract, 
                                        SalesTable          _salesTable, 
                                        SalesLine           _salesLine)
    {
        List                        matchedAutoChargeLineRecIdList;
        ListEnumerator              enumerator;
        MarkupAutoLine              markupAutoLine;

        MarkupTrans                 markupTrans;
        MarkupTable                 markupTable;
        MarkupAmount                calculatedAmount;
        TaxAmount                   calculatedTaxAmount;

        METPriceDataExtract         priceDataExtract = _priceDataExtract;
            
        matchedAutoChargeLineRecIdList = _simulatedAutoCharges.getMarkupAutoLines();

        enumerator = matchedAutoChargeLineRecIdList.getEnumerator();
        
        while (enumerator.moveNext())
        {
            markupAutoLine = MarkupAutoLine::metFindByRecId(str2int64(enumerator.current()));
            
            markupTrans = _simulatedAutoCharges.initializeMarkupTransFromParent(markupAutoLine);

            markupTable = MarkupTable::find(markupTrans.ModuleType, markupTrans.MarkupCode);

            calculatedAmount = Markup::calcTrans(markupTrans,
                                                    _salesLine.SalesQty,
                                                    _salesLine.SalesPrice,
                                                    0,      // Intercompany price requirements
                                                    todayDate);

            calculatedTaxAmount = Tax::calcTaxAmount(_priceDataExtract.TaxGroup,
                                                            markupTable.TaxItemGroup,
                                                            todayDate,
                                                            _salesTable.currencyCode,
                                                            calculatedAmount,
                                                            TaxModuleType::Sales);

            priceDataExtract.LineTotalChargeAmount      += calculatedAmount;
            priceDataExtract.LineTotalChargeTaxAmount   += calculatedTaxAmount;

            priceDataExtract.LineChargeCode     = this.pipeConcatenate(priceDataExtract.LineChargeCode, markupTrans.MarkupCode);
            priceDataExtract.LineChargeAmount   = this.pipeConcatenate(priceDataExtract.LineChargeAmount, this.numToString(calculatedAmount));
            priceDataExtract.LineChargeTaxCode  = this.pipeConcatenate(priceDataExtract.LineChargeTaxCode, markupTable.TaxItemGroup);
            priceDataExtract.LineChargeTaxAmount = this.pipeConcatenate(priceDataExtract.LineChargeTaxAmount, this.numToString(calculatedTaxAmount));

            priceDataExtract.LineAmount += calculatedAmount;
            priceDataExtract.NetAmount  = this.numToString(priceDataExtract.LineAmount);
        }
    }

    /// <summary>
    /// build a simulated sales table
    /// </summary>
    /// <param name = "_priceDataExtract">Price data extract</param>
    /// <returns>Sales table</returns>
    public SalesTable buildSalesTableTmp(METPriceDataExtract _priceDataExtract)
    {
        SalesTable  salesTable;

        salesTable.clear();
        salesTable.initValue();
        salesTable.SalesId       = guid2Str(newGuid()); //dont consume genuine salesId from Number seq as this is only a temp record.
        salesTable.CustAccount   = _priceDataExtract.CustAccount;
        salesTable.initFromCustTable();
        salesTable.CurrencyCode  = _priceDataExtract.CurrencyCode ? _priceDataExtract.CurrencyCode : salesTable.CurrencyCode;
        salesTable.ShippingDateRequested = _priceDataExtract.StartDate;

        return salesTable;
    }

    /// <summary>
    /// build a simulated sales line
    /// </summary>
    /// <param name = "_priceDataExtract">Price data extract</param>
    /// <returns>Sales line</returns>
    public SalesLine buildSalesLineTmp(METPriceDataExtract _priceDataExtract, SalesTable _salesTable)
    {
        SalesLine   salesLine;

        salesLine.clear();
        salesLine.salesId    = _salesTable.SalesId;
        salesLine.ItemId     = _priceDataExtract.itemId;
        
        salesLine.initFromSalesTable(_salesTable, false);
        salesLine.initLineFromItemOrCategory();
        salesLine.InventDimId = this.getInventDimId(_priceDataExtract.InventSiteId);
        salesLine.SalesQty    = _priceDataExtract.Qty;
        salesLine.LineAmount  = _priceDataExtract.LineAmount;               //total per the qty
        salesLine.SalesPrice  = salesLine.LineAmount / salesLine.SalesQty;  //unit price
        salesLine.InventTransId = guid2Str(newGuid());                      //dont consume genuine InventTransId from Number seq as this is only a temp record.

        return salesLine;
    }

    /// <summary>
    /// Join strings togther with Pipe seperator
    /// </summary>
    /// <param name = "_originalValue">Original String</param>
    /// <param name = "_newValue">Additional String</param>
    /// <returns>Real as a String</returns>
    public str pipeConcatenate(str _originalValue, str _newValue)
    {
        str updatedValue;

        if(_originalValue)
        {
            updatedValue = _originalValue + strFmt("@MET:Concatenate", "@MET:Pipe", _newValue);
        }
        else
        {
            updatedValue = _newValue;
        }
        return updatedValue;
    }

/// <summary>
/// Convert Real to String
/// </summary>
/// <param name = "_number">Real</param>
/// <returns>Real as a String</returns>
public str  numToString(real _number)
{
    return num2Str(_number, 4, 2, DecimalSeparator::Dot, ThousandSeparator::Comma);
}

    /// <summary>
    /// Build query for <c>MarkupAutoLine</c> records
    /// </summary>
    /// <param name = "_markupAutoTable">The <c>MarkupAutoTable</c> value</param>
    /// <returns>Query generated for <c>MarkupAutoLine</c> table based on table <c>MarkupAutoTable</c> and parameters</returns>
    public Query buildMarkupAutoLineQuery(MarkupAutoTable _markupAutoTable, MarkupTransInsertParameters _parameters)
    {
        Query ret = new Query();

        QueryBuildDataSource qbds = ret.addDataSource(tableNum(MarkupAutoLine));

        qbds.addRange(fieldNum(MarkupAutoLine, TableTableId)).value(queryValue(_markupAutoTable.TableId));
        qbds.addRange(fieldNum(MarkupAutoLine, TableRecId)).value(queryValue(_markupAutoTable.RecId));
        qbds.addRange(fieldNum(MarkupAutoLine, CurrencyCode)).value(queryValue(_parameters.Currency));
        qbds.addRange(fieldNum(MarkupAutoLine, MCRReturnMarkup)).value(queryValue(_parameters.McrReturnMarkup));

        qbds.addRange(fieldNum(MarkupAutoLine, InventSiteId)).value(queryRangeConcat(queryValue(_parameters.InventSiteId), SysQuery::valueEmptyString()));
        qbds.addRange(fieldNum(MarkupAutoLine, InventLocationId)).value(queryRangeConcat(queryValue(_parameters.InventLocationId), SysQuery::valueEmptyString()));
            
        str amountFilterStr;
            
        if (_parameters.TotalAmount <= 0)  //if _totalAmount is not positive we do not apply tiers charges
        {
            amountFilterStr = strfmt('((%1 == %3) && (%2 == %4))',
                    fieldstr(MarkupAutoLine, FromAmount),
                    fieldstr(MarkupAutoLine, ToAmount),
                    SysQuery::value(0),
                    SysQuery::value(0));
        }
        else if (_parameters.TotalAmount > 0)  //if _totalAmount is not positive we do apply tiers charges
        {
            amountFilterStr = strfmt('((%1 <= %3) && ((%2 > %4) || ((%2 == %5) && (%1 != %6))))',
                    fieldstr(MarkupAutoLine, FromAmount),
                    fieldstr(MarkupAutoLine, ToAmount),
                    SysQuery::value(_parameters.TotalAmount),
                    SysQuery::value(_parameters.TotalAmount),
                    SysQuery::value(0), //ToAmount == 0 means that we have no upper limit.
                    SysQuery::value(0)); //but it is only in the case if FromAmount is defined (not 0). Otherwise it is not a tier charge.
        }

        qbds.addRange(fieldNum(MarkupAutoLine, FromAmount)).value(amountFilterStr);
        
        PriceDate priceDate;
        str formatedDateRange;

        priceDate = todayDate;

        formatedDateRange = strFmt('(((%1 <= %3) || (%1 == %4)) && ((%2 >= %3) || (%2 == %4)))',
                                            fieldStr(MarkupAutoLine, FromDate), //%1: FromDate
                                            fieldStr(MarkupAutoLine, ToDate),   //%2: ToDate
                                            date2StrXpp(priceDate),             //%3: salesDate
                                            date2StrXpp(dateNull()));           //%4: dateNull

        qbds.addRange(fieldNum(MarkupAutoLine, FromDate)).value(formatedDateRange);

        return ret;
    }
